// Package completion generates the shell completion scripts from the registry, so the
// list of commands cannot drift from the table the dispatcher routes on.
package completion

import (
	"fmt"
	"sort"
	"strings"

	"vcod/internal/registry"
	"vcod/internal/video"
)

// Bash returns the bash completion script, which zsh also loads through bashcompinit.
func Bash() string {
	var b strings.Builder
	b.WriteString(`# vcod tab-completion (bash and zsh).
#
# Generated by: vcod completion bash
# Do not edit: regenerate it after an update so newly added commands complete.

if [ -n "${ZSH_VERSION:-}" ]; then
  autoload -Uz compinit && compinit -u 2>/dev/null
  autoload -Uz bashcompinit && bashcompinit
fi

_vcod_completions() {
  local cur prev
  cur="${COMP_WORDS[COMP_CWORD]}"
  prev="${COMP_WORDS[COMP_CWORD-1]}"

`)
	fmt.Fprintf(&b, "  local commands=%q\n", strings.Join(registry.Names(), " "))
	b.WriteString("  local flavors=\"1.5 1.6x\"\n")
	fmt.Fprintf(&b, "  local resolutions=%q\n", strings.Join(video.PresetNames(), " "))
	fmt.Fprintf(&b, "  local fpscaps=%q\n\n", strings.Join(video.FPSWords(), " "))
	b.WriteString(`  # The command already on the line, if any: global flags before it are skipped,
  # and the ones that take a value skip that too.
  local i cmd=""
  for ((i = 1; i < COMP_CWORD; i++)); do
    case "${COMP_WORDS[i]}" in
      -F|--flavor) ((i++)) ;;
      -*) ;;
      *) cmd="${COMP_WORDS[i]}"; break ;;
    esac
  done

  # Flags that take a value: offer the value, or nothing when it cannot be known here.
  case "$prev" in
    -F|--flavor)
      COMPREPLY=($(compgen -W "$flavors" -- "$cur")); return ;;
    --res|-r)
      COMPREPLY=($(compgen -W "$resolutions" -- "$cur")); return ;;
    --maxfps|--fps)
      COMPREPLY=($(compgen -W "$fpscaps" -- "$cur")); return ;;
    --display)
      COMPREPLY=($(compgen -W "window fullscreen borderless" -- "$cur")); return ;;
    --gpu)
      COMPREPLY=($(compgen -W "auto nvidia integrated" -- "$cur")); return ;;
    gpu)
      if [ "$cmd" = display ]; then COMPREPLY=($(compgen -W "auto nvidia integrated" -- "$cur")); return; fi ;;
    fps|maxfps)
      if [ "$cmd" = display ]; then COMPREPLY=($(compgen -W "$fpscaps" -- "$cur")); return; fi ;;
    -n|-p|--port|--mode|-R)
      return ;;
  esac

  if [ -z "$cmd" ]; then
    case "$cur" in
      -*)
        COMPREPLY=($(compgen -W "-F --flavor --15 --16x -w --write --json --no-color -h --help -v --version" -- "$cur")) ;;
      *)
        COMPREPLY=($(compgen -W "$commands" -- "$cur")) ;;
    esac
    return
  fi

  # A command's own candidates complete anywhere after it, so a flag still completes
  # after the username: 'vcod server start mp_carentan -<TAB>'.
  case "$cmd" in
    help)
      COMPREPLY=($(compgen -W "$commands" -- "$cur")) ;;
`)
	for _, cmd := range sortedCommands() {
		if cmd.Complete == nil {
			continue
		}
		candidates := cmd.Complete(nil)
		if len(candidates) == 0 {
			continue
		}
		fmt.Fprintf(&b, "    %s)\n      COMPREPLY=($(compgen -W %q -- \"$cur\")) ;;\n",
			cmd.Name, strings.Join(candidates, " "))
	}
	b.WriteString(`  esac
}

complete -F _vcod_completions vcod
`)
	return b.String()
}

// Fish returns the fish completion script.
func Fish() string {
	var b strings.Builder
	b.WriteString("# vcod completions for fish. Generated by: vcod completion fish\n\n")
	b.WriteString("complete -c vcod -f\n")
	for _, cmd := range sortedCommands() {
		fmt.Fprintf(&b, "complete -c vcod -n '__fish_use_subcommand' -a %s -d %s\n",
			cmd.Name, fishQuote(cmd.Summary))
		if cmd.Complete != nil {
			for _, cand := range cmd.Complete(nil) {
				fmt.Fprintf(&b, "complete -c vcod -n '__fish_seen_subcommand_from %s' -a %s\n",
					cmd.Name, fishQuote(cand))
			}
		}
	}
	b.WriteString("complete -c vcod -s F -l flavor -x -a '1.5 1.6x' -d 'Flavor for this command only'\n")
	b.WriteString("complete -c vcod -l 15 -d 'Flavor 1.5'\n")
	b.WriteString("complete -c vcod -l 16x -d 'Flavor 1.6x'\n")
	b.WriteString("complete -c vcod -l json -d 'JSON output where offered'\n")
	b.WriteString("complete -c vcod -s w -l write -d 'Write mode (destructive commands) for this command'\n")
	b.WriteString("complete -c vcod -l no-color -d 'Plain output'\n")
	b.WriteString("complete -c vcod -s h -l help -d 'Help'\n")
	b.WriteString("complete -c vcod -s v -l version -d 'Version'\n")
	return b.String()
}

func fishQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `\'`) + "'"
}

func sortedCommands() []*registry.Command {
	cmds := registry.All()
	sort.Slice(cmds, func(i, j int) bool { return cmds[i].Name < cmds[j].Name })
	return cmds
}
